#:property InvariantGlobalization=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar (from 0001-01-01)
// and count total Friday the 13ths in a full 400-year cycle.

// --- Earliest Friday the 13th ---
DateOnly earliest = default;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            if (earliest == default)
            {
                earliest = d;
                Console.WriteLine($"Earliest Friday the 13th: {d:yyyy-MM-dd} ({d.DayOfWeek})");
            }
        }
    }
}

// --- Count in a full 400-year cycle (years 1–400) ---
int count = 0;
var byMonth = new int[13];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            byMonth[month]++;
        }
    }
}

Console.WriteLine($"\nFriday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();
Console.WriteLine("Breakdown by month:");
for (int m = 1; m <= 12; m++)
{
    Console.WriteLine($"  {new DateOnly(2000, m, 1):MMMM,-12} {byMonth[m],3}");
}

// --- Which day-of-week lands on the 13th most often? ---
Console.WriteLine();
Console.WriteLine("13th falls on each day-of-week (per 400-year cycle):");
var byDay = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        byDay[(int)new DateOnly(year, month, 13).DayOfWeek]++;
    }
}
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
{
    string marker = dow == DayOfWeek.Friday ? " <-- most common!" : "";
    Console.WriteLine($"  {dow,-10} {byDay[(int)dow],3}{marker}");
}

